def check_closer_than(numbers, threshold):
    """
    Checks if any two numbers in a list are closer than the threshold.

    Args:
        numbers: List of numbers
        threshold: The minimum distance threshold

    Returns:
        True if any two numbers are closer than the threshold, False otherwise
    """
    if len(numbers) < 2:
        return False

    sorted_numbers = sorted(numbers)

    return any(
        abs(sorted_numbers[i] - sorted_numbers[i + 1]) < threshold
        for i in range(len(sorted_numbers) - 1)
    )

