def sort_numbers(numbers: str) -> str:
    # Map the word representations to their integer values
    mapping = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9
    }

    # Inverse map to convert integers back to words
    inverse_mapping = {v: k for k, v in mapping.items()}

    # Functional pipeline:
    # 1. Split string into a list of words
    # 2. Map words to integers
    # 3. Sort the integers
    # 4. Map integers back to words
    # 5. Join the words back into a string
    return ' '.join(
        inverse_mapping[num] 
        for num in sorted(
            mapping[word] 
            for word in numbers.split()
        )
    )

# Example usage:
# print(sort_numbers('three one five')) 
# Output: 'one three five'
