def largest_prime_divisor(n):
    """
    Find the largest prime divisor of a given integer n.
    """
    if n < 2:
        return None

    n = abs(n)

    # Handle the factor 2 separately
    while n % 2 == 0:
        last_factor = 2
        n //= 2

    # Handle odd factors
    d = 3
    max_factor = n
    while d * d <= n:
        if n % d == 0:
            last_factor = d
            while n % d == 0:
                n //= d
            max_factor = n
        d += 2

    # If n > 1 at this point, it is a prime factor
    return max_factor if n > 1 else last_factor

def main():
    try:
        line = input().strip()
        if not line:
            return
        n = int(line)
        print(largest_prime_divisor(n))
    except (ValueError, EOFError):
        pass

