def split_or_count(s: str):
    """
    Splits the string by whitespace if any whitespace is present.
    Otherwise splits on commas.
    If neither separator is present, counts the number of lowercase letters
    that have an odd 0‑based index in the alphabet (b, d, f, …).
    Returns a list of substrings or an integer count.
    """
    if any(ch.isspace() for ch in s):
        return s.split()
    if ',' in s:
        return s.split(',')
    # Count lowercase letters with odd 0‑based alphabet index
    return sum(
        1
        for ch in s
        if ch.islower() and (ord(ch) - ord('a')) % 2 == 1
    )
